n_hex = ""

e_hex = "0x10001"

d_hex = ""

ct = ""

n = int(n_hex, 16)
e = int(e_hex, 16)
d = int(d_hex, 16)

ct = bytes.fromhex(ct)

# Little here means little endian
# step 1
ct = int.from_bytes(ct, "little")

# step 2
m = pow(ct, d, n)

print("Raw message m:: ", m)

# step 3
flag = m.to_bytes(256, "little").rstrip(b"\x00")

print("Flag plaintext (ascii)", flag.decode("ascii"))
